def gradedSignTwist (k : ℕ) : A →ₗ[K] A :=
  (DirectSum.toModule K ℕ A (fun j => ((-1 : K) ^ (k * j)) • (𝒜 j).subtype)).comp
    (DirectSum.decomposeLinearEquiv 𝒜).toLinearMap

